#include<bits/stdc++.h>
using namespace std;

int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){
        scanf("%d",&par[i]);
        ch[par[i]].push_back(i);
    }

    // Find leaves
    vector<int>leaves;
    for(int i=1;i<=N;i++) if(ch[i].empty()) leaves.push_back(i);

    int K=0;
    // bags: list of sets; edges: adjacency
    vector<vector<int>> bags;
    vector<pair<int,int>> edges;

    auto addBag=[&](vector<int> b)->int{
        bags.push_back(b);
        return K++;
    };
    auto addEdge=[&](int a,int b){
        if(a>=0 && b>=0 && a!=b) edges.push_back({a,b});
    };

    // For each node, store leftmost leaf, rightmost leaf in its subtree
    vector<int> lLeaf(N+1), rLeaf(N+1);
    // For each node, store the "top bag" index - a bag containing {node, par(node)} (or just node for root)
    // and the "left connector" bag (contains lLeaf) and "right connector" bag (contains rLeaf)
    vector<int> topBag(N+1,-1), leftBag(N+1,-1), rightBag(N+1,-1);

    // Process bottom-up (reverse order since preorder numbering)
    for(int v=N;v>=1;v--){
        if(ch[v].empty()){
            // Leaf
            lLeaf[v]=rLeaf[v]=v;
            int p=par[v];
            // Create bag {v, p} or just {v} if root (root can't be leaf given constraints)
            vector<int> b;
            if(p) b={v,p}; else b={v};
            int id=addBag(b);
            topBag[v]=leftBag[v]=rightBag[v]=id;
        } else {
            lLeaf[v]=lLeaf[ch[v][0]];
            rLeaf[v]=rLeaf[ch[v].back()];
            int p=par[v];
            // Create chain of bags for consecutive children
            // For child ci: bag contains {v, p, rLeaf[ci], lLeaf[ci+1]} for i<k-1
            // First and last handle boundary
            int sz=ch[v].size();
            int prevBagId=-1;
            vector<int> chainBags;
            for(int i=0;i<sz;i++){
                int c=ch[v][i];
                vector<int> b;
                b.push_back(v);
                if(p) b.push_back(p);
                if(i>0) b.push_back(lLeaf[c]);
                if(i<sz-1) b.push_back(rLeaf[c]);
                // deduplicate
                sort(b.begin(),b.end());
                b.erase(unique(b.begin(),b.end()),b.end());
                if((int)b.size()>4) b.resize(4);
                int id=addBag(b);
                chainBags.push_back(id);
                if(prevBagId>=0) addEdge(prevBagId,id);
                // connect to child's top bag
                addEdge(id,topBag[c]);
                prevBagId=id;
            }
            topBag[v]=chainBags[0];
            leftBag[v]=chainBags[0];
            rightBag[v]=chainBags.back();
        }
    }

    // Handle ring edge: last leaf to first leaf
    if(leaves.size()>=2){
        int a=leaves.back(), b=leaves[0];
        vector<int> bg={a,b};
        int id=addBag(bg);
        addEdge(id, topBag[1]);
    }

    printf("%d\n",K);
    for(int i=0;i<K;i++){
        printf("%d",(int)bags[i].size());
        for(int x:bags[i]) printf(" %d",x);
        printf("\n");
    }
    for(auto&[a,b]:edges) printf("%d %d\n",a+1,b+1);
}
